-- RoseOne shared-data foundation. Review and apply in Supabase SQL Editor before enabling these tables.
-- No demo/sample rows are inserted by this migration.
create extension if not exists pgcrypto;
create table if not exists public.roseone_profiles (id uuid primary key references auth.users(id) on delete cascade, handle text unique, display_name text, avatar_url text, bio text not null default '', created_at timestamptz not null default now());
create table if not exists public.roseone_settings (user_id uuid primary key references auth.users(id) on delete cascade, preferences jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table if not exists public.roseone_posts (id uuid primary key default gen_random_uuid(), author_id uuid not null references auth.users(id) on delete cascade, body text not null default '', media jsonb not null default '[]'::jsonb, visibility text not null default 'public' check (visibility in ('public','followers','private')), created_at timestamptz not null default now());
create table if not exists public.roseone_stores (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null check (char_length(name) between 3 and 60), slug text not null unique, description text not null default '', category text not null, location text not null default '', logo_path text, cover_path text, created_at timestamptz not null default now());
create table if not exists public.roseone_marketplace_listings (id uuid primary key default gen_random_uuid(), seller_id uuid not null references auth.users(id) on delete cascade, store_id uuid references public.roseone_stores(id) on delete set null, title text not null, description text not null default '', category text not null, subcategory text, price numeric(14,2) not null check (price >= 0), currency text not null default 'NGN', condition text, location text not null default '', attributes jsonb not null default '{}'::jsonb, media_paths jsonb not null default '[]'::jsonb, status text not null default 'available' check (status in ('available','reserved','sold','removed')), created_at timestamptz not null default now());
create table if not exists public.roseone_store_follows (store_id uuid not null references public.roseone_stores(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now(), primary key (store_id, user_id));
create table if not exists public.roseone_videos (id uuid primary key default gen_random_uuid(), creator_id uuid not null references auth.users(id) on delete cascade, storage_path text not null, caption text not null default '', duration_seconds integer not null check (duration_seconds > 0 and duration_seconds <= 1800), visibility text not null default 'public' check (visibility in ('public','followers','private')), processing_status text not null default 'pending' check (processing_status in ('pending','processing','ready','failed')), created_at timestamptz not null default now());
create index if not exists roseone_posts_created_at_idx on public.roseone_posts(created_at desc);
create index if not exists roseone_listings_category_idx on public.roseone_marketplace_listings(category, subcategory, created_at desc);
create index if not exists roseone_stores_name_idx on public.roseone_stores using gin (to_tsvector('simple', name || ' ' || description || ' ' || category || ' ' || location));
create index if not exists roseone_videos_created_at_idx on public.roseone_videos(created_at desc);
alter table public.roseone_profiles enable row level security;
alter table public.roseone_settings enable row level security;
alter table public.roseone_posts enable row level security;
alter table public.roseone_stores enable row level security;
alter table public.roseone_marketplace_listings enable row level security;
alter table public.roseone_store_follows enable row level security;
alter table public.roseone_videos enable row level security;
drop policy if exists "profiles readable" on public.roseone_profiles; create policy "profiles readable" on public.roseone_profiles for select using (true);
drop policy if exists "profile owner insert" on public.roseone_profiles; create policy "profile owner insert" on public.roseone_profiles for insert with check (auth.uid() = id);
drop policy if exists "profile owner update" on public.roseone_profiles; create policy "profile owner update" on public.roseone_profiles for update using (auth.uid() = id) with check (auth.uid() = id);
drop policy if exists "settings owner only" on public.roseone_settings; create policy "settings owner only" on public.roseone_settings for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
drop policy if exists "public posts readable" on public.roseone_posts; create policy "public posts readable" on public.roseone_posts for select using (visibility = 'public' or auth.uid() = author_id);
drop policy if exists "post owner insert" on public.roseone_posts; create policy "post owner insert" on public.roseone_posts for insert with check (auth.uid() = author_id);
drop policy if exists "post owner update delete" on public.roseone_posts; create policy "post owner update delete" on public.roseone_posts for all using (auth.uid() = author_id) with check (auth.uid() = author_id);
drop policy if exists "stores publicly readable" on public.roseone_stores; create policy "stores publicly readable" on public.roseone_stores for select using (true);
drop policy if exists "store owner insert" on public.roseone_stores; create policy "store owner insert" on public.roseone_stores for insert with check (auth.uid() = owner_id);
drop policy if exists "store owner update delete" on public.roseone_stores; create policy "store owner update delete" on public.roseone_stores for all using (auth.uid() = owner_id) with check (auth.uid() = owner_id);
drop policy if exists "available listings readable" on public.roseone_marketplace_listings; create policy "available listings readable" on public.roseone_marketplace_listings for select using (status <> 'removed' or auth.uid() = seller_id);
drop policy if exists "listing owner insert" on public.roseone_marketplace_listings; create policy "listing owner insert" on public.roseone_marketplace_listings for insert with check (auth.uid() = seller_id);
drop policy if exists "listing owner update delete" on public.roseone_marketplace_listings; create policy "listing owner update delete" on public.roseone_marketplace_listings for all using (auth.uid() = seller_id) with check (auth.uid() = seller_id);
drop policy if exists "store follows visible" on public.roseone_store_follows; create policy "store follows visible" on public.roseone_store_follows for select using (true);
drop policy if exists "users manage own follows" on public.roseone_store_follows; create policy "users manage own follows" on public.roseone_store_follows for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
drop policy if exists "public videos readable" on public.roseone_videos; create policy "public videos readable" on public.roseone_videos for select using (visibility = 'public' or auth.uid() = creator_id);
drop policy if exists "video owner insert" on public.roseone_videos; create policy "video owner insert" on public.roseone_videos for insert with check (auth.uid() = creator_id);
drop policy if exists "video owner update delete" on public.roseone_videos; create policy "video owner update delete" on public.roseone_videos for all using (auth.uid() = creator_id) with check (auth.uid() = creator_id);
